export type Difficulty = "easy" | "medium" | "hard" | "expert";
export type Rules = { mode: "classic" | "quick"; safeSquares: boolean; threeSixes: boolean };
export type PlayerInput = { id?: string; name: string; color: number; type: "human" | "ai"; difficulty?: Difficulty };
export type Player = Required<PlayerInput> & { pieces: number[] };
export type Capture = { player: number; piece: number; from: number };
export type GameEvent = { id: number; type: string; player: number; turn: number; text: string };
export type RollAction = { id: number; type: "roll"; player: number; face: number; dice: number; noMoves: boolean; forfeit: boolean; extraTurn: boolean };
export type MoveAction = { id: number; type: "move"; player: number; piece: number; from: number; to: number; face: number; dice: number; captured: Capture[]; extraTurn: boolean; won: boolean };
export type GameState = {
  players: Player[]; rules: Rules; current: number; phase: "roll" | "move" | "finished";
  dice: number | null; sixes: number; turn: number; revision: number; winner: number | null;
  legal: number[]; events: GameEvent[]; lastAction: RollAction | MoveAction | null;
};
export const COLORS: readonly { id: string; index: number; name: string; hex: string; light: string; dark: string }[];
export const TRACK: readonly (readonly [number, number])[];
export const STARTS: readonly number[];
export const SAFE_SQUARES: readonly number[];
export const HOME_LANES: readonly (readonly (readonly [number, number])[])[];
export const FINISH: number;
export const DIFFICULTIES: readonly Difficulty[];
export function fairDie(): number;
export function normalizeRules(rules?: Partial<Rules>): Rules;
export function createGame(players: PlayerInput[], rules?: Partial<Rules>): GameState;
export function trackIndex(color: number, progress: number): number | null;
export function isSafeSquare(state: GameState, absoluteIndex: number): boolean;
export function legalMoves(state: GameState): number[];
export function applyRoll(state: GameState, face: number): GameState;
export function applyMove(state: GameState, piece: number): GameState;
export function chooseMove(state: GameState, difficulty?: Difficulty): number | null;
